internal static class LoginFormScripts {
 internal const string Resolver="const visible=e=>{if(!e||e.isConnected===false)return false;if(typeof e.closest==='function'&&e.closest('[hidden],[aria-hidden=true],.grecaptcha-badge,[data-testid*=badge i]'))return false;const s=typeof getComputedStyle==='function'?getComputedStyle(e):null;return (!s||s.display!=='none'&&s.visibility!=='hidden'&&s.visibility!=='collapse'&&s.opacity!=='0')&&e.getBoundingClientRect().width>0&&e.getBoundingClientRect().height>0;};const challenge=()=>{const t=(document.body?(document.body.innerText||''):'').toLowerCase();return Array.from(document.querySelectorAll('[role=dialog],[aria-modal=true],iframe[src*=captcha i],iframe[src*=arkose i],iframe[title*=captcha i],iframe[title*=challenge i],[data-testid=captcha],[data-testid=captcha-challenge]')).some(visible)||/verify you(?: are|['’]re) human|security challenge|ยืนยันว่าคุณเป็นมนุษย์/.test(t)||/hold the button/.test(t)&&/press and hold/.test(t);};const unique=a=>a.length===1?a[0]:null;const u=unique(Array.from(document.querySelectorAll('#login-username')).filter(visible)),p=unique(Array.from(document.querySelectorAll('#login-password')).filter(visible));const legacy=Array.from(document.querySelectorAll('#login-button')).filter(visible);const formButtons=p?.form?Array.from(p.form.querySelectorAll('button[type=submit]')).filter(visible):[];const named=Array.from(document.querySelectorAll('button')).filter(e=>e.type==='submit'&&/^(sign in|log in|เข้าสู่ระบบ|ลงชื่อเข้าใช้)$/i.test((e.textContent||'').trim())&&visible(e));const b=legacy.length?unique(legacy):formButtons.length?unique(formButtons):unique(named);";
 internal const string ReadyBody="return !!(u&&p&&b&&!u.disabled&&!p.disabled&&!u.readOnly&&!p.readOnly&&!challenge());";
 internal const string FillBody="if(!u||!p||!b||u.disabled||p.disabled||u.readOnly||p.readOnly||challenge()||typeof username!=='string'||typeof password!=='string'||!username||!password)return false;if((u.value&&u.value!==username)||(p.value&&p.value!==password))return false;const set=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;set.call(u,username);u.dispatchEvent(new Event('input',{bubbles:true}));u.dispatchEvent(new Event('change',{bubbles:true}));set.call(p,password);p.dispatchEvent(new Event('input',{bubbles:true}));p.dispatchEvent(new Event('change',{bubbles:true}));return true;";
 internal const string CheckFilledBody="if(challenge())return 'CHALLENGE';if(!u||!p||!b)return 'MISSING';if((typeof username==='string'&&u.value&&u.value!==username)||(typeof password==='string'&&p.value&&p.value!==password))return 'MISMATCH';if(!u.value||!p.value)return 'EMPTY';return 'MATCHED';";
 internal const string SubmitBody="if(challenge())return 'CHALLENGE';if(!u||!p||!b)return 'MISSING';if((typeof username==='string'&&u.value&&u.value!==username)||(typeof password==='string'&&p.value&&p.value!==password))return 'MISMATCH';if(!u.value||!p.value)return 'EMPTY';if(b.disabled||b.getAttribute('aria-disabled')==='true')return 'PENDING';b.click();return 'CLICKED';";
 internal static string Ready {get{return "(()=>{"+Resolver+ReadyBody+"})()";}}
 internal static string Fill(string usernameJson,string passwordJson){return "((username,password)=>{"+Resolver+FillBody+"})("+usernameJson+","+passwordJson+")";}
