 // This guard also works when a challenge has replaced every login control.
 // An unlabelled dialog is a pause signal; Issue below supplies a precise code
 // only when visible content identifies the verification or login problem.
 internal const string ChallengeVisibleBody="const visible=e=>{if(!e||e.isConnected===false)return false;if(typeof e.closest==='function'&&e.closest('[hidden],[aria-hidden=true],.grecaptcha-badge,[data-testid*=badge i]'))return false;const s=typeof getComputedStyle==='function'?getComputedStyle(e):null;return (!s||s.display!=='none'&&s.visibility!=='hidden'&&s.visibility!=='collapse'&&s.opacity!=='0')&&e.getBoundingClientRect().width>0&&e.getBoundingClientRect().height>0;};return Array.from(document.querySelectorAll('[role=dialog],[aria-modal=true],iframe[src*=captcha i],iframe[src*=arkose i],iframe[title*=captcha i],iframe[title*=challenge i],[data-testid=captcha],[data-testid=captcha-challenge]')).some(visible);";
 internal static string ChallengeVisible {get{return "(()=>{"+ChallengeVisibleBody+"})()";}}
 // Broader than the original detector: the live page reports a rejected login as
 // plain body text ("Incorrect username or password."), not as an alert, and it
 // also shows mail-code, passkey and rate-limit screens after the password step.
 internal const string IssueBody="const t=(document.body?(document.body.innerText||''):'').toLowerCase();const shown=e=>{if(!e||e.isConnected===false)return false;if(typeof e.closest==='function'&&e.closest('[hidden],[aria-hidden=true],.grecaptcha-badge,[data-testid*=badge i]'))return false;const s=typeof getComputedStyle==='function'?getComputedStyle(e):null;return (!s||s.display!=='none'&&s.visibility!=='hidden'&&s.visibility!=='collapse'&&s.opacity!=='0')&&e.getBoundingClientRect().width>0&&e.getBoundingClientRect().height>0;};const visible=s=>Array.from(document.querySelectorAll(s)).some(shown);if(visible('iframe[src*=captcha i],iframe[src*=arkose i],iframe[title*=captcha i],iframe[title*=challenge i],[data-testid=captcha],[data-testid=captcha-challenge]')||/verify you(?: are|['’]re) human|security challenge|ยืนยันว่าคุณเป็นมนุษย์/.test(t)||/hold the button/.test(t)&&/press and hold/.test(t)||Array.from(document.querySelectorAll('[role=dialog],[aria-modal=true]')).some(e=>shown(e)&&/^(press and hold|hold the button)[.!…]*$/i.test((e.innerText||'').trim())))return 'CUSTOMER_CAPTCHA_REQUIRED';if(visible('input[autocomplete=one-time-code]')||/verification code|two.step verification|2.step verification|enter the code|check your email|รหัสยืนยัน|กรอกรหัส|ตรวจอีเมล/.test(t))return 'CUSTOMER_OTP_REQUIRED';if(/verify (using|with|on) (your )?(phone|mobile)|check your (phone|mobile)|approve (the )?(login|request)|โปรดเปิดแอป roblox|โทรศัพท์มือถือหรือแท็บเล็ตที่ลงชื่อเข้าใช้อยู่/.test(t))return 'CUSTOMER_PHONE_VERIFICATION';if(/verify (it.s|your identity|your account)|confirm your identity|sign in with a passkey|use your passkey|ยืนยันตัวตน|ตรวจสอบตัวตน|พาสคีย์/.test(t))return 'CUSTOMER_IDENTITY_VERIFICATION';if(/too many (attempts|requests|tries)|พยายามหลายครั้งเกินไป|บ่อยเกินไป/.test(t))return 'CUSTOMER_LOGIN_RATE_LIMITED';if(/incorrect (username|password)|username or password you entered is incorrect|invalid (username|password)|wrong password|ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง|รหัสผ่านไม่ถูกต้อง|รหัสผ่านผิด/.test(t))return 'CUSTOMER_PASSWORD_INVALID';return '';";
 internal static string Issue {get{return "(()=>{"+IssueBody+"})()";}}
 internal const string ViewBody="const raw=(document.body?(document.body.innerText||''):'').split(String.fromCharCode(13)).join(' ').split(String.fromCharCode(10)).join(' ');const redacted=username?raw.split(username).join('***'):raw;return JSON.stringify({path:location.pathname,text:redacted.slice(0,300)});";
 internal static string View(string usernameJson){return "((username)=>{"+ViewBody+"})("+usernameJson+")";}
